import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";

type PipelineLastResult = {
  returncode?: number | null;
  stdout?: string;
  stderr?: string;
  started_at?: string;
  finished_at?: string;
  duration_seconds?: number;
  material_count?: number;
  asset_count?: number;
  variant_count?: number;
};

type PipelineStatus = {
  running?: boolean;
  current_step?: string;
  step?: string;
  material_count?: number;
  asset_count?: number;
  variant_count?: number;
  runtime_seconds?: number;
  started_at?: string;
  updated_at?: string;
  last_result?: PipelineLastResult | null;
};

type BroadcastState = {
  isLive: boolean;
  liveStartedAt: number | null;
  currentMaterialName: string;
  ttsStatus: "idle" | "speaking" | "queued" | "error";
  commentCount: number;
};

const API = {
  run: "/api/pipeline/run",
  status: "/api/pipeline/status",
};

function formatDuration(seconds?: number | null): string {
  if (seconds == null || Number.isNaN(seconds)) return "--:--";

  const safeSeconds = Math.max(0, Math.floor(seconds));
  const h = Math.floor(safeSeconds / 3600);
  const m = Math.floor((safeSeconds % 3600) / 60);
  const s = safeSeconds % 60;

  if (h > 0) {
    return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }

  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

function formatClock(ts: number | null): string {
  if (!ts) return "--:--";
  const diffSeconds = Math.floor((Date.now() - ts) / 1000);
  return formatDuration(diffSeconds);
}

function readNumber(...values: Array<number | undefined | null>): number {
  for (const value of values) {
    if (typeof value === "number" && Number.isFinite(value)) {
      return value;
    }
  }
  return 0;
}

function parseCountFromText(text: string | undefined, patterns: RegExp[]): number | undefined {
  if (!text) return undefined;

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match?.[1]) {
      const value = Number(match[1]);
      if (Number.isFinite(value)) return value;
    }
  }

  return undefined;
}

function getMaterialCount(status: PipelineStatus | null): number {
  const stdout = status?.last_result?.stdout;

  return readNumber(
    status?.material_count,
    status?.asset_count,
    status?.last_result?.material_count,
    status?.last_result?.asset_count,
    parseCountFromText(stdout, [
      /material(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /asset(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /素材(?:数|数量)?\s*[:：=]\s*(\d+)/i,
      /产物(?:数|数量)?\s*[:：=]\s*(\d+)/i,
    ])
  );
}

function getVariantCount(status: PipelineStatus | null): number {
  const stdout = status?.last_result?.stdout;

  return readNumber(
    status?.variant_count,
    status?.last_result?.variant_count,
    parseCountFromText(stdout, [
      /variant(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /变体(?:数|数量)?\s*[:：=]\s*(\d+)/i,
    ])
  );
}

function getRuntimeSeconds(status: PipelineStatus | null): number | undefined {
  if (!status) return undefined;

  if (typeof status.runtime_seconds === "number") {
    return status.runtime_seconds;
  }

  if (typeof status.last_result?.duration_seconds === "number") {
    return status.last_result.duration_seconds;
  }

  if (status.started_at) {
    const started = new Date(status.started_at).getTime();
    if (Number.isFinite(started)) {
      return Math.max(0, Math.floor((Date.now() - started) / 1000));
    }
  }

  if (status.last_result?.started_at && status.last_result?.finished_at) {
    const started = new Date(status.last_result.started_at).getTime();
    const finished = new Date(status.last_result.finished_at).getTime();

    if (Number.isFinite(started) && Number.isFinite(finished)) {
      return Math.max(0, Math.floor((finished - started) / 1000));
    }
  }

  return undefined;
}

function getCurrentStep(status: PipelineStatus | null): string {
  if (!status) return "等待启动";

  if (status.running) {
    return status.current_step || status.step || "管线运行中";
  }

  const returncode = status.last_result?.returncode;

  if (returncode === 0) return "最近一次运行成功";
  if (typeof returncode === "number" && returncode !== 0) return "最近一次运行失败";

  return status.current_step || status.step || "空闲";
}

function getPipelineHealth(status: PipelineStatus | null): {
  label: string;
  tone: "ok" | "warn" | "idle" | "running";
} {
  if (!status) {
    return {
      label: "未连接",
      tone: "warn",
    };
  }

  if (status.running) {
    return {
      label: "管线运行中",
      tone: "running",
    };
  }

  const returncode = status.last_result?.returncode;

  if (returncode === 0) {
    return {
      label: "运行成功",
      tone: "ok",
    };
  }

  if (typeof returncode === "number" && returncode !== 0) {
    return {
      label: "运行异常",
      tone: "warn",
    };
  }

  return {
    label: "待启动",
    tone: "idle",
  };
}

