              <div className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-red-200">
                STDERR
              </div>

              <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-words text-xs leading-6 text-[oklch(82%_0_0)]">
                {lastStderr || "暂无 stderr 输出"}
              </pre>
            </div>
          </div>
        </section>
      </section>
    </main>
  );
}
